llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Radiolabeled umeclidinium studies in healthy volunteers showed systemic bioavailability of oral and inhaled drug is ≤12%, indicating very low oral absorption for a quaternary ammonium antimuscarinic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "The UK SPC reports absolute bioavailability of lercanidipine (Zanidip) orally administered to patients under fed conditions is around 10%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DX-9065a exhibited human oral bioavailability of only 2–3%, attributed to its strong basic amidino groups, illustrating charge-related poor oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Terfenadine is listed with innate oral drug bioavailability <5% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Pravastatin shows an absolute oral bioavailability of 18% at oral doses of 40–80 mg, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In a final pharmacokinetic model for the (R)-enantiomer of this ester/amine drug, oral bioavailability was estimated at 0.0669 (95% CI 0.0567–0.0813).",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lercanidipine absolute bioavailability was about 30% after a single 10 mg oral dose in healthy volunteers and patients, a condition-dependent value above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium antimuscarinic (butylscopolamine-like) expected to have poor membrane permeability. The strongest transferable evidence, umeclidinium (another quaternary ammonium antimuscarinic), shows ≤12% systemic bioavailability. Additional low-F evidence from DX-9065, pravastatin, terfenadine, oxybutynin, and fed lercanidipine supports F <20%. A single lercanidipine record of 30% F is condition-dependent and outweighed by the charge-related absorption barrier.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; extrapolation relies on quaternary ammonium analogues.",
    "Lercanidipine F varies with prandial state (30% vs 10%), and its relevance to a permanently charged quaternary ammonium is uncertain.",
    "The query's exact permeability, efflux, and first-pass metabolism profile is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

